import Foundation
@testable import HassCore
import Testing

// MARK: - The state golden

/// Checks the new state words, glyphs and tones against the answers of the frozen old app, over the generic state space.
///
/// `StateGolden/state-space.json` is one row per (tile kind, variant, entity state), generated by `tools/state_space/generate.py`
/// from the hand-kept registry and the Home Assistant state sets. `StateGolden/state-golden.json` is what the old `HassCore`
/// (`native@4fe28061`, built in a temp checkout by `tools/state_golden/generate.py`) answers for each row: the text, the
/// activity, the disc's verb, glyph, `isOn` and phase. This suite evaluates the same rows with the current code and compares
/// field by field.
///
/// A difference is never silenced. `StateGolden/expected-failures.json` lists every one with a class (`native`, `config`,
/// `studio` or `fixture`) and a reason; the suite fails on a difference the manifest does not list and on a manifest entry the
/// code no longer produces, so a fix flips its entry out of the file. An entry with `fixedBy` names the lane that fixes it.
///
/// The remote device line is evaluated by ``CurrentRemoteLine``, a mirror of the line `UKServerUIRemoteAtoms` draws today. The
/// `state-text-core` lane moves that line into `ServerUIRemoteDeviceText.line`; when it lands, `CurrentRemoteLine` calls it and the
/// `fixedBy: state-text-core` entries leave the manifest.
@Suite(.timeLimit(.minutes(2)))
struct StateGoldenTests {
    // MARK: Files

    static let directory = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("StateGolden", isDirectory: true)

    /// One state-space row, as the generator writes it.
    struct Row: Decodable, Sendable {
        struct Option: Decodable, Sendable { let value: String; let label: String }
        let id: String
        let kind: String
        let entity_id: String
        let state: String?
        let attributes: [String: JSONValue]
        let options: [Option]?
    }

    /// One kind of the registry, as far as the evaluator needs.
    struct Kind: Decodable, Sendable {
        let id: String
        let evaluator: String
        let room_kind: String?
        let style: String?
        let old: String?
    }

    /// One group of expected differences.
    struct Expected: Decodable, Sendable {
        let field: String
        let `class`: String
        let reason: String
        let fixedBy: String?
        let ids: [String]
    }

    /// A difference between the old answer and the new one.
    struct Mismatch: Hashable, Comparable, Sendable {
        let id: String
        let field: String
        let old: String
        let new: String
        static func < (lhs: Mismatch, rhs: Mismatch) -> Bool { (lhs.id, lhs.field) < (rhs.id, rhs.field) }
        var key: String { "\(id)#\(field)" }
    }

    private struct Space: Decodable { let rows: [Row] }
    private struct Registry: Decodable { let kinds: [Kind] }
    private struct Golden: Decodable { let pin: String; let hassCoreTree: String; let rowCount: Int; let rows: [String: JSONValue] }

    private static func load<T: Decodable>(_ type: T.Type, _ name: String) -> T {
        do { return try JSONDecoder().decode(T.self, from: Data(contentsOf: directory.appendingPathComponent(name))) }
        catch { fatalError("StateGolden/\(name): \(error)") }
    }

    nonisolated(unsafe) static let rows: [Row] = load(Space.self, "state-space.json").rows
    nonisolated(unsafe) private static let golden = load(Golden.self, "state-golden.json")
    nonisolated(unsafe) static let expected: [Expected] = load([Expected].self, "expected-failures.json")
    nonisolated(unsafe) static let kinds: [String: Kind] = {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().appendingPathComponent("tools/state_space/kinds.json")
        guard let registry = try? JSONDecoder().decode(Registry.self, from: Data(contentsOf: url)) else { fatalError("kinds.json") }
        return Dictionary(uniqueKeysWithValues: registry.kinds.map { ($0.id, $0) })
    }()

    // MARK: Evaluation

    /// The line a remote device or card draws today (`UKServerUIRemoteAtoms.swift`, `states.first { $0.value == display.state }?.label ?? fallback`),
    /// kept in the shape of `ServerUIRemoteDeviceText.line` so the swap is one call.
    enum CurrentRemoteLine {
        static func line(isUnavailable: Bool, unavailable: String, state: String, options: [Row.Option], controllerText: String?,
                         fallback: String) -> String {
            if isUnavailable { return unavailable }
            return options.first { $0.value == state }?.label ?? fallback
        }
    }

    /// The text of a JSON value as the comparison reads it: strings bare, booleans `true` and `false`, null `nil`.
    static func text(_ value: JSONValue?) -> String {
        switch value {
        case .string(let s)?: s
        case .bool(let b)?: b ? "true" : "false"
        case .number(let n)?: String(n)
        case .array(let items)?: "[" + items.map { text($0) }.joined(separator: ", ") + "]"
        case .null?, nil: "nil"
        case .object?: "{...}"
        }
    }

    /// The fields the new code gives for one row. Keys match the golden's.
    static func evaluate(_ row: Row, kind: Kind) -> [String: String] {
        let entity = row.state.map { EntityState(entityId: row.entity_id, state: $0, attributes: row.attributes) }
        func flag(_ value: Bool) -> String { value ? "true" : "false" }
        switch kind.evaluator {
        case "room-text":
            var out = ["text": RoomFormat.withUnit(entity), "compact": RoomFormat.compact(entity), "active": flag(RoomFormat.isActive(entity))]
            if kind.room_kind == "occupancy" { out["occupancy"] = RoomFormat.occupancy(entity); out["occupied"] = flag(RoomFormat.isOccupied(entity)) }
            if kind.room_kind == "contact" {
                out["contact"] = RoomFormat.contact(entity); out["open"] = flag(RoomFormat.isOpen(entity))
                out["tileSubtitle"] = RoomFormat.contactTileSubtitle(entity)
            }
            return out
        case "remote-device":
            let shown = row.state ?? "unavailable"
            let unavailable = EntityState.isUnavailable(shown)
            // The controller's own text for a state with no authored label (`MediaRemoteController.display`).
            let line = CurrentRemoteLine.line(isUnavailable: unavailable, unavailable: "Unavailable", state: shown,
                                              options: row.options ?? [], controllerText: MediaRemoteState.format(shown), fallback: "Unknown")
            return ["line": line, "unavailable": flag(unavailable)]
        case "style":
            guard let id = kind.style, let style = StateStyle.builtIn(id: id) else { return [:] }
            var out: [String: String] = [:]
            let resolution = style.resolve(entity, entityId: row.entity_id)
            out["words"] = resolution.words
            if let spec = style.spec(for: entity, entityId: row.entity_id) {
                out["verb"] = spec.verb; out["symbol"] = spec.symbol; out["phase"] = "\(spec.phase)"
                out["isOn"] = spec.isOn.map(flag) ?? "nil"; out["confirms"] = flag(spec.confirmation != nil)
            } else {
                for field in ["verb", "symbol", "phase", "isOn", "confirms"] { out[field] = "nil" }
            }
            return out
        default:
            return [:]
        }
    }

    /// Every difference between the golden and the current code, in row order.
    static func mismatches() -> [Mismatch] {
        var out: [Mismatch] = []
        for row in rows {
            guard case .object(let old)? = golden.rows[row.id], let kind = kinds[row.kind] else { continue }
            let new = evaluate(row, kind: kind)
            for (field, value) in old.sorted(by: { $0.key < $1.key }) {
                switch field {
                case "candidates":
                    // The old provider's declared words: the new words must be among them.
                    let words = new["words"] ?? "nil"
                    if case .array(let items) = value, !items.contains(where: { text($0) == words }) {
                        out.append(Mismatch(id: row.id, field: "words", old: text(value), new: words))
                    }
                case "actions":
                    continue // the old vacuum disc pair has no counterpart in the robot style, which draws no disc
                default:
                    let now = new[field] ?? "nil"
                    if text(value) != now { out.append(Mismatch(id: row.id, field: field, old: text(value), new: now)) }
                }
            }
        }
        return out
    }

    static let classes: Set<String> = ["native", "config", "studio", "fixture"]

    // MARK: Tests

    @Test func theGoldenRecordsItsPinAndCoversTheSpace() {
        #expect(Self.golden.pin == "4fe28061")
        #expect(Self.golden.hassCoreTree.count == 40)
        #expect(Self.golden.rowCount == Self.golden.rows.count)
        let ids = Set(Self.rows.map(\.id))
        #expect(Self.rows.count == ids.count, "a state-space row id repeats")
        #expect(Set(Self.golden.rows.keys).isSubset(of: ids), "the golden has a row the state space does not")
        // A kind has golden rows exactly when the registry names an old oracle for it.
        let oracleKinds = Set(Self.rows.filter { Self.golden.rows[$0.id] != nil }.map(\.kind))
        for (id, kind) in Self.kinds {
            let hasOracle = kind.evaluator != "style" || kind.old != nil
            #expect(oracleKinds.contains(id) == hasOracle, "\(id): oracle \(hasOracle) but golden rows \(oracleKinds.contains(id))")
        }
    }

    @Test func everyKindOfTheSpaceIsRegistered() {
        #expect(Set(Self.rows.map(\.kind)).isSubset(of: Set(Self.kinds.keys)))
        #expect(Set(Self.kinds.keys) == Set(Self.rows.map(\.kind)), "a registry kind generated no rows")
    }

    @Test func theManifestIsWellFormed() {
        var seen = Set<String>()
        for item in Self.expected {
            #expect(Self.classes.contains(item.class), "unknown class \(item.class)")
            #expect(!item.reason.isEmpty)
            #expect(!item.ids.isEmpty)
            for id in item.ids {
                #expect(seen.insert("\(id)#\(item.field)").inserted, "\(id) \(item.field) is listed twice")
                #expect(Self.golden.rows[id] != nil, "\(id) is not a golden row")
            }
        }
    }

    /// The core check: current code against the old answers, with every difference named in the manifest and none left over.
    @Test func everyDifferenceFromTheOldAppIsListedAndNoneIsStale() {
        let actual = Self.mismatches()
        if let path = ProcessInfo.processInfo.environment["STATE_GOLDEN_DUMP"] {
            let lines = actual.map { "\($0.key)\t\($0.old)\t\($0.new)" }.joined(separator: "\n")
            try? lines.write(toFile: path, atomically: true, encoding: .utf8)
        }
        let listed = Set(Self.expected.flatMap { item in item.ids.map { "\($0)#\(item.field)" } })
        let unlisted = actual.filter { !listed.contains($0.key) }
        let stale = listed.subtracting(actual.map(\.key))
        #expect(unlisted.isEmpty, "differences from the old app not in expected-failures.json: \(unlisted.map { "\($0.key) old=\($0.old) new=\($0.new)" })")
        #expect(stale.isEmpty, "manifest entries the code no longer produces (flip them out): \(stale.sorted())")
    }

    /// The counts the lane reports, kept in step with the manifest so a drift shows as a test failure and not a stale note.
    @Test func theManifestCountsByClassAndByFix() {
        var byClass: [String: Int] = [:]
        var fixed = 0
        for item in Self.expected {
            byClass[item.class, default: 0] += item.ids.count
            if item.fixedBy != nil { fixed += item.ids.count }
        }
        #expect(byClass.values.reduce(0, +) == Self.expected.reduce(0) { $0 + $1.ids.count })
        #expect(fixed <= Self.expected.reduce(0) { $0 + $1.ids.count })
        #expect(Self.expected.allSatisfy { $0.fixedBy == nil || $0.fixedBy == "state-text-core" })
    }

    // MARK: What the old words were (pinned, independent of the files)

    /// The PC case in three rows: the old tile read a text helper and raised its first letter; the device line shows the controller's
    /// words for a state with no authored label.
    @Test func theOldWordsOfThePCCaseAreInTheGolden() {
        func fields(_ id: String) -> [String: JSONValue] {
            guard case .object(let o)? = Self.golden.rows[id] else { return [:] }
            return o
        }
        #expect(Self.text(fields("room-power.helper.demo-ready")["text"]) == "Demo ready")
        #expect(Self.text(fields("room-power.helper.demo-busy")["text"]) == "Demo Busy...")
        #expect(Self.text(fields("remote-device.options-none.off")["line"]) == "Off")
        #expect(Self.text(fields("remote-device.options-none.unknown")["line"]) == "Unknown")
    }

    @Test func theCurrentDeviceLineDropsTheControllerText() {
        let none = CurrentRemoteLine.line(isUnavailable: false, unavailable: "Unavailable", state: "off", options: [], controllerText: "Off", fallback: "Unknown")
        #expect(none == "Unknown", "when this reads Off, state-text-core has landed: call ServerUIRemoteDeviceText.line and empty the fixedBy entries")
    }
}
